fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    assert!(n >= 2, "list must have length at least 2");
    assert!(k >= 1 && k < n, "k must satisfy 1 <= k < n (1-based indexing)");

    // Convert to 0-based index of the element to remove.
    let idx = k - 1;

    let mut out = Vec::with_capacity(n - 1);
    out.extend_from_slice(&list[..idx]);       // elements before idx
    out.extend_from_slice(&list[idx + 1..]);   // elements after idx
    out
}

// Optional quick check
fn main() {
    let v = vec![10, 20, 30, 40];
    assert_eq!(remove_kth_element(&v, 1), vec![20, 30, 40]); // remove first
    assert_eq!(remove_kth_element(&v, 2), vec![10, 30, 40]); // remove middle
    assert_eq!(remove_kth_element(&v, 3), vec![10, 20, 40]); // remove middle
    // k = 4 would panic because removing last is not allowed by the problem.
}